**Todo List App**

**Key Features:**

1. User can add, remove, and edit tasks by category
2. Tasks can be categorized into different groups (e.g., work, personal, leisure)
3. Tasks can be assigned a priority level (e.g., high, medium, low)
4. Tasks can be marked as completed
5. User can view all tasks, filtered by category and priority

**Code:**

```python
class TodoList:
    def __init__(self):
        self.tasks = {}

    def add_task(self, category, task, priority):
        if category not in self.tasks:
            self.tasks[category] = {}
        if task not in self.tasks[category]:
            self.tasks[category][task] = {'priority': priority, 'completed': False}
        return f"Task '{task}' added to '{category}'"

    def remove_task(self, category, task):
        if category in self.tasks and task in self.tasks[category]:
            del self.tasks[category][task]
            return f"Task '{task}' removed from '{category}'"
        return f"Task '{task}' not found in '{category}'"

    def edit_task(self, category, task, new_priority):
        if category in self.tasks and task in self.tasks[category]:
            self.tasks[category][task]['priority'] = new_priority
            return f"Task '{task}' updated to '{new_priority}' in '{category}'"
        return f"Task '{task}' not found in '{category}'"

    def complete_task(self, category, task):
        if category in self.tasks and task in self.tasks[category]:
            self.tasks[category][task]['completed'] = True
            return f"Task '{task}' marked as completed in '{category}'"
        return f"Task '{task}' not found in '{category}'"

    def view_tasks(self, category=None, priority=None):
        if category:
            if category in self.tasks:
                return f"Tasks in '{category}':\n"
                for task, details in self.tasks[category].items():
                    if details['completed']:
                        return f"- {task} (Completed)"
                    else:
                        return f"- {task} (Not Completed)"
            else:
                return "Category not found"
        elif priority:
            if priority in self.tasks:
                return f"Tasks in '{priority}'\n"
                for task, details in self.tasks[priority].items():
                    if details['completed']:
                        return f"- {task} (Completed)"
                    else:
                        return f"- {task} (Not Completed)"
            else:
                return "Priority not found"
        else:
            return "No tasks found"

