  title VARCHAR(100) NOT NULL,
  description TEXT,
  due_date DATE,
  priority INT,
  completed BOOLEAN DEFAULT FALSE,
  category_id INT,
  FOREIGN KEY (category_id) REFERENCES Categories(id)
);

