        // Create a HashMap
        Map<String, Integer> map = new HashMap<>();
        map.put("apple", 5);
        map.put("banana", 10);

        // Create a TreeMap
        Map<String, Integer> treeMap = new TreeMap<>();
        treeMap.put("apple", 5);
        treeMap.put("banana", 10);

        // Lookup values
